const express = require('express');
const crypto = require('crypto');
const bcrypt = require('bcryptjs');
const rateLimit = require('express-rate-limit');
const { DB } = require('../db');
const { authenticate, requireRole, signToken } = require('../middleware/auth');
const router = express.Router();
const companyAuthLimiter = rateLimit({ windowMs: 15 * 60 * 1000, limit: 8, standardHeaders: true, legacyHeaders: false });

// Company access codes are short-lived, single-use invitations generated by an admin.
router.post('/register', companyAuthLimiter, async (req, res) => {
  try {
    const name = String(req.body.companyName || '').trim(), fullName = String(req.body.fullName || '').trim();
    const phone = String(req.body.phone || '').trim(), code = String(req.body.secretCode || '').trim(), password = req.body.password;
    if (name.length < 2 || fullName.length < 2 || !phone || !code || typeof password !== 'string' || password.length < 10)
      return res.status(400).json({ success: false, error: 'Company, representative, phone, code and password (10+ characters) are required.' });
    const c = await DB.prepare("SELECT id, name FROM transport_companies WHERE LOWER(name)=LOWER(?) AND status='INVITED'").get(name);
    if (!c) return res.status(403).json({ success: false, error: 'Invalid or already-used company registration code.' });
    const accessCode = await DB.prepare("SELECT id, code_hash FROM transport_company_access_codes WHERE company_id=? AND revoked=FALSE AND expires_at > CURRENT_TIMESTAMP ORDER BY created_at DESC LIMIT 1").get(c.id);
    if (!accessCode || !accessCode.code_hash || !(await bcrypt.compare(code, accessCode.code_hash)))
      return res.status(403).json({ success: false, error: 'Invalid or already-used company registration code.' });
    const hash = await bcrypt.hash(password, 12);
    const registration = await DB.transaction(async (tx) => {
      const lockSuffix = tx.isPostgres ? ' FOR UPDATE' : '';
      const company = await tx.prepare("SELECT id, name FROM transport_companies WHERE id=? AND status='INVITED'" + lockSuffix).get(c.id);
      const currentCode = await tx.prepare("SELECT id, code_hash FROM transport_company_access_codes WHERE id=? AND company_id=? AND revoked=FALSE AND expires_at > CURRENT_TIMESTAMP" + lockSuffix).get(accessCode.id, c.id);
      if (!company || !currentCode || !(await bcrypt.compare(code, currentCode.code_hash))) return { status: 'INVALID_CODE' };
      if (tx.isPostgres) await tx.prepare("SELECT pg_advisory_xact_lock(hashtext('routepass-company-phone:' || ?))").get(phone);
      const phoneUsed = await tx.prepare('SELECT id FROM transport_companies WHERE phone = ? AND id <> ?').get(phone, c.id);
      if (phoneUsed) return { status: 'PHONE_USED' };
      const consumed = await tx.prepare("UPDATE transport_company_access_codes SET revoked=TRUE WHERE id=? AND company_id=? AND revoked=FALSE AND expires_at > CURRENT_TIMESTAMP").run(accessCode.id, c.id);
      if (consumed.changes !== 1) return { status: 'INVALID_CODE' };
      const updated = await tx.prepare("UPDATE transport_companies SET phone=?, representative_name=?, password_hash=?, status='ACTIVE', updated_at=CURRENT_TIMESTAMP WHERE id=? AND status='INVITED'")
        .run(phone, fullName, hash, c.id);
      return { status: updated.changes === 1 ? 'REGISTERED' : 'INVALID_CODE', company };
    });
    if (registration.status === 'PHONE_USED') return res.status(409).json({ success: false, error: 'Phone already registered for a company.' });
    if (registration.status !== 'REGISTERED') return res.status(403).json({ success: false, error: 'Invalid, expired, or already-used company registration code.' });
    const token = signToken({ id:c.id, role:'COMPANY', companyId:c.id, companyName:c.name, fullName, phone });
    res.status(201).json({ success:true, token, user:{ id:c.id, role:'COMPANY', companyId:c.id, companyName:c.name, fullName, phone } });
  } catch (e) { console.error('[Company] register failed:', e); res.status(500).json({ success:false, error:'Company registration failed.' }); }
});

router.post('/login', companyAuthLimiter, async (req,res) => {
  try {
    const phone=String(req.body.phone||'').trim(), password=req.body.password;
    const c=await DB.prepare("SELECT * FROM transport_companies WHERE phone=? AND status='ACTIVE'").get(phone);
    if (!c || !c.password_hash || !(await bcrypt.compare(String(password||''),c.password_hash))) return res.status(401).json({success:false,error:'Invalid company credentials.'});
    const fullName=c.representative_name||c.name;
    res.json({success:true,token:signToken({id:c.id,role:'COMPANY',companyId:c.id,companyName:c.name,fullName,phone}),user:{id:c.id,role:'COMPANY',companyId:c.id,companyName:c.name,fullName,phone}});
  } catch(e) { console.error('[Company] login failed:',e); res.status(500).json({success:false,error:'Company login failed.'}); }
});
router.get('/me', authenticate, requireRole('COMPANY'), async(req,res)=>{
  const c=await DB.prepare("SELECT id,name,phone,representative_name,status FROM transport_companies WHERE id=? AND status='ACTIVE'").get(req.user.companyId||req.user.id);
  if(!c)return res.status(404).json({success:false,error:'Company not found.'}); res.json({success:true,company:c});
});
router.get('/operations/summary',authenticate,requireRole('COMPANY'),async(req,res)=>{
  try {
    const id=req.user.companyId||req.user.id;
    const drivers=await DB.prepare("SELECT COUNT(*) AS count FROM users WHERE role='DRIVER' AND companyId=?").get(id);
    const vehicles=await DB.prepare('SELECT COUNT(*) AS count FROM vehicles WHERE companyId=?').get(id);
    const assignments=await DB.prepare("SELECT COUNT(*) AS count FROM company_route_assignments WHERE company_id=? AND status='ACTIVE'").get(id);
    const cutoff = new Date(Date.now() - 120000).toISOString().replace('T', ' ').replace('Z', '');
    const gps=await DB.prepare("SELECT COUNT(*) AS count FROM vehicles v JOIN vehicle_live_locations l ON l.vehicle_id=v.id WHERE v.companyId=? AND l.updated_at >= ?").get(id,cutoff);
    res.json({success:true,summary:{drivers:+drivers.count,vehicles:+vehicles.count,activeAssignments:+assignments.count,vehiclesReportingGps:+gps.count}});
  } catch(e){console.error('[Company] summary:',e);res.status(500).json({success:false,error:'Company summary unavailable.'});}
});
router.get('/operations/fleet',authenticate,requireRole('COMPANY'),async(req,res)=>{
 try{const id=req.user.companyId||req.user.id;
 const vehicles=await DB.prepare('SELECT v.id,v.plateNumber,v.model,v.vehicleType,v.capacityLimit,v.currentOccupancy,v.status,v.driverId,v.driverName,v.assignedRouteId,r.name AS routeName,l.latitude,l.longitude,l.speed,l.updated_at AS lastGpsAt FROM vehicles v LEFT JOIN routes r ON r.id=v.assignedRouteId LEFT JOIN vehicle_live_locations l ON l.vehicle_id=v.id WHERE v.companyId=? ORDER BY v.plateNumber').all(id);
 const drivers=await DB.prepare("SELECT id,fullName,phone,status,licenseNumber FROM users WHERE role='DRIVER' AND companyId=? ORDER BY fullName").all(id);
 res.json({success:true,vehicles,drivers});}catch(e){console.error('[Company] fleet:',e);res.status(500).json({success:false,error:'Fleet unavailable.'});}
});
router.post('/operations/vehicles', authenticate, requireRole('COMPANY'), async (req,res)=>{
  try {
    const companyId=req.user.companyId||req.user.id;
    const plateNumber=String(req.body.plateNumber||'').trim().toUpperCase();
    const model=String(req.body.model||'').trim();
    const vehicleType=String(req.body.vehicleType||'MINIBUS_14').trim().toUpperCase();
    const capacities={MINIVAN_8:8,MINIBUS_14:14,HIGER_24:24,ANBESSA_BUS_30:30};
    if(!plateNumber||!model||!capacities[vehicleType])return res.status(400).json({success:false,error:'Plate, model and supported vehicle type are required.'});
    const duplicate=await DB.prepare('SELECT id FROM vehicles WHERE plateNumber=?').get(plateNumber);
    if(duplicate)return res.status(409).json({success:false,error:'Vehicle plate already exists.'});
    const id='veh_'+crypto.randomUUID().replace(/-/g,'').slice(0,12);
    await DB.prepare("INSERT INTO vehicles(id,plateNumber,model,vehicleType,capacityLimit,currentOccupancy,assignedRouteId,driverId,driverName,status,companyId) VALUES(?,?,?,?,?,0,NULL,NULL,'','OFF_DUTY',?)").run(id,plateNumber,model,vehicleType,capacities[vehicleType],companyId);
    res.status(201).json({success:true,vehicle:{id,plateNumber,model,vehicleType,capacityLimit:capacities[vehicleType],companyId,status:'OFF_DUTY'}});
  }catch(e){console.error('[Company] vehicle registration failed:',e);res.status(500).json({success:false,error:'Could not register company vehicle.'});}
});

router.get('/operations/routes',authenticate,requireRole('COMPANY'),async(req,res)=>{
 try{const cid=req.user.companyId||req.user.id; const routes=await DB.prepare("SELECT r.*, a.id AS assignment_id, a.status AS assignment_status, a.driver_id, a.vehicle_id FROM routes r LEFT JOIN company_route_assignments a ON a.route_id=r.id AND a.company_id=? AND a.status='ACTIVE' WHERE r.companyId=? AND r.routeType='INTERCITY' ORDER BY r.name").all(cid,cid);res.json({success:true,routes});}
 catch(e){console.error('[Company] routes:',e);res.status(500).json({success:false,error:'Company routes unavailable.'});}
});
router.post('/operations/assignments',authenticate,requireRole('COMPANY'),async(req,res)=>{
 try{
 const cid=req.user.companyId||req.user.id, routeId=String(req.body.routeId||''),driverId=String(req.body.driverId||''),vehicleId=String(req.body.vehicleId||'');
 if(!routeId||!driverId||!vehicleId)return res.status(400).json({success:false,error:'Route, driver and company vehicle are required.'});
 const id='cassign_'+crypto.randomUUID().replace(/-/g,'').slice(0,16);
 const result=await DB.transaction(async(tx)=>{
   const lockSuffix=tx.isPostgres?' FOR UPDATE':'';
   const r=await tx.prepare("SELECT id FROM routes WHERE id=? AND companyId=? AND routeType='INTERCITY' AND active=TRUE"+lockSuffix).get(routeId,cid);
   const d=await tx.prepare("SELECT id FROM users WHERE id=? AND role='DRIVER' AND companyId=? AND status='ACTIVE'"+lockSuffix).get(driverId,cid);
   const v=await tx.prepare('SELECT id FROM vehicles WHERE id=? AND companyId=?'+lockSuffix).get(vehicleId,cid);
   if(!r||!d||!v)return {status:'INVALID_SCOPE'};
   const activeTrip=await tx.prepare("SELECT id FROM trips WHERE vehicleId=? AND status='IN_PROGRESS' LIMIT 1").get(vehicleId);
   if(activeTrip)return {status:'ACTIVE_TRIP'};
   const activeDeparture=await tx.prepare("SELECT id FROM intercity_departures WHERE vehicle_id=? AND status='BOARDING' LIMIT 1").get(vehicleId);
   if(activeDeparture)return {status:'ACTIVE_TRIP'};
   const conflict=await tx.prepare("SELECT id FROM company_route_assignments WHERE status='ACTIVE' AND (driver_id=? OR vehicle_id=?) LIMIT 1").get(driverId,vehicleId);
   if(conflict)return {status:'CONFLICT'};
   await tx.prepare("INSERT INTO company_route_assignments(id,company_id,route_id,driver_id,vehicle_id,status) VALUES(?,?,?,?,?,'ACTIVE')").run(id,cid,routeId,driverId,vehicleId);
   await tx.prepare("UPDATE vehicles SET driverId=?,driverName=(SELECT fullName FROM users WHERE id=?),assignedRouteId=?,status='IN_SERVICE',updatedAt=CURRENT_TIMESTAMP WHERE id=? AND companyId=?")
     .run(driverId,driverId,routeId,vehicleId,cid);
   await tx.prepare('INSERT INTO audit_logs (action,userId,role,details) VALUES (?,?,?,?)')
     .run('COMPANY_ROUTE_ASSIGNED',req.user.id,'COMPANY',`Assigned driver ${driverId} and vehicle ${vehicleId} to route ${routeId}`);
   return {status:'CREATED'};
 });
 if(result.status==='INVALID_SCOPE')return res.status(403).json({success:false,error:'Route, driver and vehicle must be active and belong to this company.'});
 if(result.status==='ACTIVE_TRIP')return res.status(409).json({success:false,error:'End the vehicle’s active trip before assigning it.'});
 if(result.status==='CONFLICT')return res.status(409).json({success:false,error:'Driver or vehicle already has an active assignment.'});
 res.status(201).json({success:true,assignment:{id,companyId:cid,routeId,driverId,vehicleId,status:'ACTIVE'}});
 }catch(e){console.error('[Company] assignment:',e);res.status(500).json({success:false,error:'Could not assign route.'});}
});

router.delete('/operations/assignments/:id',authenticate,requireRole('COMPANY'),async(req,res)=>{
 try{
   const cid=req.user.companyId||req.user.id;
   const result=await DB.transaction(async(tx)=>{
     const lockSuffix=tx.isPostgres?' FOR UPDATE':'';
     const assignment=await tx.prepare("SELECT * FROM company_route_assignments WHERE id=? AND company_id=? AND status='ACTIVE'"+lockSuffix).get(req.params.id,cid);
     if(!assignment)return {status:'NOT_FOUND'};
     const vehicle=await tx.prepare('SELECT id FROM vehicles WHERE id=? AND companyId=?'+lockSuffix).get(assignment.vehicle_id,cid);
     if(!vehicle)return {status:'NOT_FOUND'};
     const trip=await tx.prepare("SELECT id FROM trips WHERE vehicleId=? AND status='IN_PROGRESS' LIMIT 1").get(vehicle.id);
     if(trip)return {status:'ACTIVE_TRIP'};
     const departure=await tx.prepare("SELECT id FROM intercity_departures WHERE vehicle_id=? AND status='BOARDING' LIMIT 1").get(vehicle.id);
     if(departure)return {status:'ACTIVE_TRIP'};
     await tx.prepare("UPDATE company_route_assignments SET status='INACTIVE' WHERE id=? AND company_id=? AND status='ACTIVE'").run(assignment.id,cid);
     await tx.prepare("UPDATE vehicles SET driverId=NULL,driverName='',assignedRouteId=NULL,status='OFF_DUTY',updatedAt=CURRENT_TIMESTAMP WHERE id=? AND companyId=? AND driverId=?")
       .run(vehicle.id,cid,assignment.driver_id);
     await tx.prepare('INSERT INTO audit_logs (action,userId,role,details) VALUES (?,?,?,?)')
       .run('COMPANY_ROUTE_UNASSIGNED',req.user.id,'COMPANY',`Unassigned vehicle ${vehicle.id} from route ${assignment.route_id}`);
     return {status:'UNASSIGNED'};
   });
   if(result.status==='NOT_FOUND')return res.status(404).json({success:false,error:'Active assignment not found for this company.'});
   if(result.status==='ACTIVE_TRIP')return res.status(409).json({success:false,error:'End the vehicle’s active trip before removing this assignment.'});
   res.json({success:true,message:'Assignment removed. The vehicle remains registered to your company.'});
 }catch(e){console.error('[Company] unassign:',e);res.status(500).json({success:false,error:'Could not remove assignment.'});}
});

/** Company-scoped driver approvals. */
router.get('/operations/drivers', authenticate, requireRole('COMPANY'), async (req,res) => {
  try { const companyId=req.user.companyId||req.user.id;
    const drivers=await DB.prepare("SELECT id,fullName,phone,licenseNumber,status,companyName,companyId,createdAt FROM users WHERE role='DRIVER' AND companyId=? ORDER BY id DESC").all(companyId);
    res.json({success:true,drivers});
  } catch(e){console.error('[Company] drivers:',e);res.status(500).json({success:false,error:'Could not load drivers.'});}
});
router.patch('/operations/drivers/:id/approval', authenticate, requireRole('COMPANY'), async (req,res) => {
  try { const companyId=req.user.companyId||req.user.id, action=String(req.body.action||'').toUpperCase();
    if(!['APPROVE','REJECT'].includes(action)) return res.status(400).json({success:false,error:'Choose APPROVE or REJECT.'});
    const driver=await DB.prepare("SELECT id,status FROM users WHERE id=? AND role='DRIVER' AND companyId=?").get(req.params.id,companyId);
    if(!driver) return res.status(404).json({success:false,error:'Driver not found in your company.'});
    if(driver.status!=='PENDING' && action==='APPROVE') return res.status(409).json({success:false,error:'Only pending drivers can be approved.'});
    const status=action==='APPROVE'?'ACTIVE':'SUSPENDED';
    await DB.prepare("UPDATE users SET status=? WHERE id=? AND companyId=? AND role='DRIVER'").run(status,req.params.id,companyId);
    res.json({success:true,driver:{id:req.params.id,status},message:action==='APPROVE'?'Driver approved. Assign a company vehicle and route next.':'Driver application rejected.'});
  } catch(e){console.error('[Company] driver approval:',e);res.status(500).json({success:false,error:'Could not update driver approval.'});}
});

/** Company-owned routes. */
router.post('/operations/routes', authenticate, requireRole('COMPANY'), async (req,res) => {
  try {
    const companyId=req.user.companyId||req.user.id;
    const name=String(req.body.name||'').trim(), nameAm=String(req.body.nameAm||name).trim();
    const routeType=String(req.body.routeType||'INTERCITY').toUpperCase();
    const origin=String(req.body.origin||'').trim(), destination=String(req.body.destination||'').trim();
    const departureTime=String(req.body.departureTime||req.body.morningDeparture||(routeType==='INTERCITY'?'08:00':'06:30')).trim();
    if(name.length<2) return res.status(400).json({success:false,error:'Route name is required.'});
    if(routeType!=='INTERCITY') return res.status(400).json({success:false,error:'Companies manage Intercity routes only.'});
    if(origin.length<2||destination.length<2) return res.status(400).json({success:false,error:'Departure/origin and destination are required.'});
    if(origin.toLowerCase()===destination.toLowerCase()) return res.status(400).json({success:false,error:'Departure and destination must be different.'});
    const morningDeparture=routeType==='INTERCITY'?departureTime:String(req.body.morningDeparture||'06:30');
    const eveningDeparture=routeType==='INTERCITY'?departureTime:String(req.body.eveningDeparture||'17:30');
    const id='route_'+crypto.randomUUID().replace(/-/g,'').slice(0,12);
    await DB.prepare('INSERT INTO routes (id,name,nameAm,description,morningDeparture,eveningDeparture,distanceKm,basePriceEtb,active,companyId,routeType,origin,destination,departureTime) VALUES (?,?,?,?,?,?,?,?,TRUE,?,?,?,?,?)')
      .run(id,name,nameAm,String(req.body.description||'').trim(),morningDeparture,eveningDeparture,Math.max(0.1,Number(req.body.distanceKm)||10),Math.max(0,Number(req.body.basePriceEtb)||0),companyId,routeType,origin,destination,departureTime);
    res.status(201).json({success:true,route:await DB.prepare('SELECT * FROM routes WHERE id=? AND companyId=?').get(id,companyId)});
  } catch(e){console.error('[Company] create route:',e);res.status(500).json({success:false,error:'Could not create route. Check that the company route migration has been applied.'});}
});
router.put('/operations/routes/:id', authenticate, requireRole('COMPANY'), async (req,res) => {
  try {
    const companyId=req.user.companyId||req.user.id, current=await DB.prepare('SELECT * FROM routes WHERE id=? AND companyId=?').get(req.params.id,companyId);
    if(!current) return res.status(404).json({success:false,error:'Route not found for this company.'});
    const name=String(req.body.name??current.name).trim(), nameAm=String(req.body.nameAm??current.nameAm??name).trim();
    const routeType=String(req.body.routeType??current.routeType??'INTERCITY').toUpperCase();
    const origin=String(req.body.origin??current.origin??'').trim(), destination=String(req.body.destination??current.destination??'').trim();
    const departureTime=String(req.body.departureTime??current.departureTime??req.body.morningDeparture??current.morningDeparture??'06:30').trim();
    if(!name) return res.status(400).json({success:false,error:'Route name is required.'});
    if(routeType!=='INTERCITY') return res.status(400).json({success:false,error:'Companies manage Intercity routes only.'});
    if(origin.length<2||destination.length<2) return res.status(400).json({success:false,error:'Departure/origin and destination are required.'});
    if(origin.toLowerCase()===destination.toLowerCase()) return res.status(400).json({success:false,error:'Departure and destination must be different.'});
    const morningDeparture=routeType==='INTERCITY'?departureTime:String(req.body.morningDeparture??current.morningDeparture??'06:30');
    const eveningDeparture=routeType==='INTERCITY'?departureTime:String(req.body.eveningDeparture??current.eveningDeparture??'17:30');
    await DB.prepare('UPDATE routes SET name=?,nameAm=?,description=?,morningDeparture=?,eveningDeparture=?,distanceKm=?,basePriceEtb=?,active=?,routeType=?,origin=?,destination=?,departureTime=? WHERE id=? AND companyId=?')
      .run(name,nameAm,String(req.body.description??current.description??''),morningDeparture,eveningDeparture,Math.max(0.1,Number(req.body.distanceKm??current.distanceKm)||10),Math.max(0,Number(req.body.basePriceEtb??current.basePriceEtb)||0),req.body.active===undefined?current.active:Boolean(req.body.active),routeType,origin,destination,departureTime,req.params.id,companyId);
    res.json({success:true,route:await DB.prepare('SELECT * FROM routes WHERE id=? AND companyId=?').get(req.params.id,companyId)});
  } catch(e){console.error('[Company] update route:',e);res.status(500).json({success:false,error:'Could not update route.'});}
});

/** Bookings and passenger roster limited to this company's active route assignments. */
router.get('/operations/bookings', authenticate, requireRole('COMPANY'), async (req,res) => {
  try { const companyId=req.user.companyId||req.user.id;
    const bookings=await DB.prepare(`
      SELECT s.id AS subscription_id,s.subscriptionStatus AS subscription_status,s.paymentStatus AS payment_status,
        s.startDate AS start_date,s.endDate AS end_date,s.daysRemaining AS days_remaining,
        s.pickupStopId AS pickup_stop_id,s.destinationStopId AS destination_stop_id,
        u.id AS passenger_id,u.fullName AS passenger_name,u.phone AS passenger_phone,
        r.id AS route_id,r.name AS route_name,a.driver_id,a.vehicle_id,
        v.plateNumber AS vehicle_plate,v.model AS vehicle_model
      FROM subscriptions s JOIN users u ON u.id=s.passengerId JOIN routes r ON r.id=s.routeId
      JOIN company_route_assignments a ON a.route_id=r.id AND a.company_id=? AND a.status='ACTIVE'
      LEFT JOIN vehicles v ON v.id=a.vehicle_id
      WHERE r.routeType='INTERCITY' AND s.subscriptionStatus='ACTIVE' AND s.paymentStatus='PAID' AND s.daysRemaining>0
      ORDER BY r.name,u.fullName
    `).all(companyId);
    const roster=await DB.prepare(`
      SELECT c.id AS checkin_id,c.tripId AS trip_id,c.passengerId AS passenger_id,c.passengerName AS passenger_name,
        c.routeId AS route_id,c.stopName AS stop_name,c.status,c.timestamp,c.vehicleId AS vehicle_id,c.driverId AS driver_id
      FROM checkin_records c JOIN routes r ON r.id=c.routeId AND r.routeType='INTERCITY' JOIN company_route_assignments a ON a.route_id=c.routeId AND a.company_id=? AND a.status='ACTIVE'
      ORDER BY c.timestamp DESC LIMIT 500
    `).all(companyId);
    res.json({success:true,bookings,roster});
  } catch(e){console.error('[Company] bookings/roster:',e);res.status(500).json({success:false,error:'Could not load booking details and passenger roster.'});}
});

module.exports=router;
